resolver = "2"

[workspace.package]
version = "0.8.5"
edition = "2024"
license = "MIT OR Apache-2.0"
repository = "https://github.com/zeroclaw-labs/zeroclaw"
homepage = "https://www.zeroclaw.com"
rust-version = "1.96.0"

[workspace.dependencies]
zeroclaw-api = { path = "crates/zeroclaw-api", version = "0.8.5" }
zeroclaw-infra = { path = "crates/zeroclaw-infra", version = "0.8.5" }
zeroclaw-config = { path = "crates/zeroclaw-config", version = "0.8.5", default-features = false }
zeroclaw-log = { path = "crates/zeroclaw-log", version = "0.8.5" }
zeroclaw-tls = { path = "crates/zeroclaw-tls", version = "0.8.5" }
zeroclaw-relay-proto = { path = "crates/zeroclaw-relay-proto", version = "0.8.5" }
zerorelay = { path = "apps/zerorelay", version = "0.8.5" }
zeroclaw-spawn = { path = "crates/zeroclaw-spawn", version = "0.8.5" }
zeroclaw-commands = { path = "crates/zeroclaw-commands", version = "0.8.5" }
zeroclaw-providers = { path = "crates/zeroclaw-providers", version = "0.8.5" }
zeroclaw-memory = { path = "crates/zeroclaw-memory", version = "0.8.5" }
zeroclaw-channels = { path = "crates/zeroclaw-channels", version = "0.8.5", default-features = false }
zeroclaw-tools = { path = "crates/zeroclaw-tools", version = "0.8.5" }
zeroclaw-sop-graph = { path = "crates/zeroclaw-sop-graph", version = "0.8.5", default-features = false }
zeroclaw-runtime = { path = "crates/zeroclaw-runtime", version = "0.8.5", default-features = false }
zeroclaw-eval = { path = "crates/zeroclaw-eval", version = "0.8.5" }
zeroclaw-plugins = { path = "crates/zeroclaw-plugins", version = "0.8.5" }
zeroclaw-gateway = { path = "crates/zeroclaw-gateway", version = "0.8.5" }
zeroclaw-hardware = { path = "crates/zeroclaw-hardware", version = "0.8.5" }
zeroclaw-tool-call-parser = { path = "crates/zeroclaw-tool-call-parser", version = "0.8.5" }
zeroclaw-macros = { path = "crates/zeroclaw-macros", version = "0.8.5" }
zerocode = { path = "apps/zerocode", version = "0.8.5" }
directories = "6.0"
sys-locale = "0.3"

[package]
name = "zeroclaw"
# Workspace crates are publish = false during microkernel transition.
publish = true
default-run = "zeroclaw"
version.workspace = true
edition.workspace = true
authors = ["theonlyhennygod"]
license.workspace = true
description = "Zero overhead. Zero compromise. 100% Rust. The fastest, smallest AI assistant."
repository.workspace = true
homepage.workspace = true
documentation = "https://docs.zeroclaw.com"
readme = "README.md"
keywords = ["ai", "agent", "cli", "assistant", "chatbot"]
categories = ["command-line-utilities", "api-bindings"]
rust-version.workspace = true
include = [
  "/src/**/*",
  "/build.rs",
  "/Cargo.toml",
  "/Cargo.lock",
  "/LICENSE*",
  "/README.md",
  "/web/dist/**/*",
  "/locales/**/*",
]

[[bin]]
name = "zeroclaw"
path = "src/main.rs"

[[bin]]
name = "zeroclaw-acp-bridge"
path = "src/bin/zeroclaw-acp-bridge.rs"
required-features = ["acp-bridge"]

[lib]
name = "zeroclaw"
path = "src/lib.rs"

[dependencies]
# Internal workspace crates — versions and paths declared once in [workspace.dependencies]
zeroclaw-api.workspace = true
zeroclaw-spawn.workspace = true
zeroclaw-infra.workspace = true
zeroclaw-config = { workspace = true, features = ["clap"] }
zeroclaw-log.workspace = true
zeroclaw-providers.workspace = true
zeroclaw-memory.workspace = true
zeroclaw-channels = { workspace = true, optional = true }
zeroclaw-tools = { workspace = true, optional = true }
zeroclaw-runtime = { workspace = true, optional = true }
zeroclaw-tls = { workspace = true }
zeroclaw-eval = { workspace = true, optional = true }
zeroclaw-plugins = { workspace = true, optional = true }
zeroclaw-gateway = { workspace = true, optional = true }
zeroclaw-hardware = { workspace = true, optional = true }
zeroclaw-tool-call-parser.workspace = true
zeroclaw-macros.workspace = true
# CLI - minimal and fast
clap = { versio
